"""Chrome browser scanner — matches the Go chromedp implementation.

Flow (same as Go's ChromeScan):
1. Find Chrome binary, get version
2. Discover profiles from Local State JSON
3. Copy essential profile files to temp directory
4. For each profile: launch headless Chrome via CDP, navigate, screenshot, get cookies
5. macOS fallback: if headless returned 0 cookies, read from Cookies SQLite DB
   with keychain-derived AES decryption (same as Go's readCookiesFromDB)
6. Clean up temp copy
"""

from __future__ import annotations

import base64
import hashlib
import json
import os
import platform
import shutil
import sqlite3
import subprocess
import tempfile
import time
from pathlib import Path
from urllib.request import urlopen

from secretscan.model import (
    ChromeCookie,
    ChromeProfile,
    ChromeStatus,
    Module,
    ModuleStatus,
)

CHROME_RENDER_WAIT = 6
CHROME_TOTAL_BUDGET = 90
DEFAULT_CHROME_URL = "https://mail.google.com/mail/u/0/"

ESSENTIAL_PROFILE_FILES = [
    "Cookies", "Cookies-journal", "Cookies-wal", "Cookies-shm",
    "Preferences", "Secure Preferences",
    "Login Data", "Login Data-journal",
    "Web Data", "Web Data-journal",
]


# ---------------------------------------------------------------------------
# Chrome binary + user-data discovery (cross-platform, same as Go)
# ---------------------------------------------------------------------------

def _find_chrome_binary() -> str:
    system = platform.system()
    if system == "Darwin":
        home = str(Path.home())
        candidates = [
            "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
            "/Applications/Google Chrome Beta.app/Contents/MacOS/Google Chrome Beta",
            "/Applications/Chromium.app/Contents/MacOS/Chromium",
            os.path.join(home, "Applications/Google Chrome.app/Contents/MacOS/Google Chrome"),
        ]
        for c in candidates:
            if os.path.isfile(c):
                return c
    elif system == "Windows":
        for base in [os.environ.get("PROGRAMFILES", ""),
                     os.environ.get("PROGRAMFILES(X86)", ""),
                     os.environ.get("LOCALAPPDATA", "")]:
            if not base:
                continue
            candidate = os.path.join(base, "Google", "Chrome", "Application", "chrome.exe")
            if os.path.isfile(candidate):
                return candidate

    for name in ["google-chrome", "google-chrome-stable", "chromium", "chromium-browser", "chrome"]:
        path = shutil.which(name)
        if path:
            return path
    return ""


def _chrome_user_data_dir() -> str:
    home = str(Path.home())
    system = platform.system()
    if system == "Darwin":
        return os.path.join(home, "Library", "Application Support", "Google", "Chrome")
    elif system == "Linux":
        return os.path.join(home, ".config", "google-chrome")
    elif system == "Windows":
        local = os.environ.get("LOCALAPPDATA", os.path.join(home, "AppData", "Local"))
        return os.path.join(local, "Google", "Chrome", "User Data")
    return ""


# ---------------------------------------------------------------------------
# Profile discovery (same as Go's discoverProfiles)
# ---------------------------------------------------------------------------

def _discover_profiles(user_data_dir: str) -> list[dict]:
    local_state = os.path.join(user_data_dir, "Local State")
    if not os.path.isfile(local_state):
        return []
    try:
        with open(local_state, "r", errors="replace") as f:
            data = json.load(f)
        cache = data.get("profile", {}).get("info_cache", {})
        profiles = []
        for dir_name, info in sorted(cache.items()):
            profile_dir = os.path.join(user_data_dir, dir_name)
            if os.path.isdir(profile_dir):
                profiles.append({
                    "dir_name": dir_name,
                    "display_name": info.get("name", dir_name),
                    "gaia_name": info.get("gaia_name", ""),
                })
        return profiles
    except Exception:
        return []


# ---------------------------------------------------------------------------
# Copy essential profile files (same as Go's copyProfileForLaunch)
# ---------------------------------------------------------------------------

def _copy_profile_for_launch(src: str, profiles: list[dict]) -> tuple[str, int]:
    dst = tempfile.mkdtemp(prefix="secretscan-chrome-profile-")
    copied = 0

    local_state_src = os.path.join(src, "Local State")
    local_state_dst = os.path.join(dst, "Local State")
    if os.path.isfile(local_state_src):
        shutil.copy2(local_state_src, local_state_dst)
        copied += os.path.getsize(local_state_dst)

    for pinfo in profiles:
        profile_src = os.path.join(src, pinfo["dir_name"])
        profile_dst = os.path.join(dst, pinfo["dir_name"])
        os.makedirs(profile_dst, exist_ok=True)
        for fname in ESSENTIAL_PROFILE_FILES:
            src_file = os.path.join(profile_src, fname)
            if os.path.isfile(src_file):
                dst_file = os.path.join(profile_dst, fname)
                try:
                    shutil.copy2(src_file, dst_file)
                    copied += os.path.getsize(dst_file)
                except OSError:
                    pass

    return dst, copied


# ---------------------------------------------------------------------------
# Headless Chrome via CDP (same as Go's driveChrome using chromedp)
# ---------------------------------------------------------------------------

def _cdp_send(ws, method: str, params: dict | None = None, msg_id: int = 1) -> dict:
    msg = json.dumps({"id": msg_id, "method": method, "params": params or {}})
    ws.send(msg)
    deadline = time.time() + 30
    while time.time() < deadline:
        raw = ws.recv()
        resp = json.loads(raw)
        if resp.get("id") == msg_id:
            return resp
    return {}


def _find_page_ws(port: int) -> str:
    """Get the WebSocket URL for the first page target (for Page-level commands)."""
    try:
        resp = urlopen(f"http://127.0.0.1:{port}/json", timeout=2)
        targets = json.loads(resp.read())
        for t in targets:
            if t.get("type") == "page":
                return t.get("webSocketDebuggerUrl", "")
    except Exception:
        pass
    return ""


def _drive_chrome(
    binary: str, user_data_dir: str, profile_dir: str, url: str,
) -> tuple[bytes, list[ChromeCookie], str]:
    """Launch headless Chrome, navigate, screenshot, read cookies via CDP.

    Returns (screenshot_png, cookies, error_string) — same contract as Go's driveChrome.
    Uses page-level WebSocket for navigation + screenshot, browser-level for cookies
    (matching chromedp's behavior).
    """
    try:
        import websocket as ws_mod
    except ImportError:
        return b"", [], "websocket-client not installed (pip install websocket-client)"

    port = 9222
    args = [
        binary,
        "--headless=new",
        f"--remote-debugging-port={port}",
        f"--user-data-dir={user_data_dir}",
        f"--profile-directory={profile_dir}",
        "--no-first-run",
        "--no-default-browser-check",
        "--disable-background-networking",
        "--disable-background-timer-throttling",
        "--disable-backgrounding-occluded-windows",
        "--disable-breakpad",
        "--disable-client-side-phishing-detection",
        "--disable-default-apps",
        "--disable-dev-shm-usage",
        "--disable-hang-monitor",
        "--disable-popup-blocking",
        "--disable-prompt-on-repost",
        "--disable-renderer-backgrounding",
        "--disable-sync",
        "--force-color-profile=srgb",
        "--metrics-recording-only",
        "--safebrowsing-disable-auto-update",
        "--enable-automation",
        "--password-store=detect",
        "--hide-scrollbars",
        "--window-size=1280,900",
        "--remote-allow-origins=*",
        url,
    ]

    proc = subprocess.Popen(args, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
    png = b""
    cookies: list[ChromeCookie] = []
    error = ""

    try:
        browser_ws_url = ""
        page_ws_url = ""
        for _ in range(30):
            time.sleep(1)
            try:
                resp = urlopen(f"http://127.0.0.1:{port}/json/version", timeout=2)
                info = json.loads(resp.read())
                browser_ws_url = info.get("webSocketDebuggerUrl", "")
                if browser_ws_url:
                    page_ws_url = _find_page_ws(port)
                    break
            except Exception:
                continue

        if not browser_ws_url:
            return b"", [], "could not connect to Chrome DevTools"

        if page_ws_url:
            page_ws = ws_mod.create_connection(page_ws_url, timeout=30)
            _cdp_send(page_ws, "Page.enable", {}, msg_id=10)
            time.sleep(CHROME_RENDER_WAIT)
            resp = _cdp_send(page_ws, "Page.captureScreenshot", {"format": "png"}, msg_id=2)
            if "result" in resp and "data" in resp["result"]:
                png = base64.b64decode(resp["result"]["data"])
            page_ws.close()

        browser_ws = ws_mod.create_connection(browser_ws_url, timeout=30)
        resp = _cdp_send(browser_ws, "Storage.getCookies", {}, msg_id=3)
        if "result" in resp:
            for c in resp["result"].get("cookies", []):
                cookies.append(ChromeCookie(
                    domain=c.get("domain", ""),
                    name=c.get("name", ""),
                    value=c.get("value", ""),
                    path=c.get("path", ""),
                    expires=c.get("expires", 0.0),
                    size=c.get("size", 0),
                    http_only=c.get("httpOnly", False),
                    secure=c.get("secure", False),
                    session=c.get("session", False),
                    same_site=str(c.get("sameSite", "")),
                ))
        browser_ws.close()
    except Exception as e:
        error = str(e)[:300]
    finally:
        try:
            proc.terminate()
            proc.wait(timeout=5)
        except Exception:
            proc.kill()

    cookies.sort(key=lambda c: (c.domain, c.name))
    return png, cookies, error


# ---------------------------------------------------------------------------
# macOS cookie decryption from SQLite (same as Go's readCookiesFromDB +
# deriveChromeKey + decryptChromeValue)
# ---------------------------------------------------------------------------

def _derive_chrome_key(password: bytes) -> bytes:
    """PBKDF2-HMAC-SHA1, salt='saltysalt', 1003 iterations, 16-byte key.

    Same as Go's deriveChromeKey.
    """
    return hashlib.pbkdf2_hmac("sha1", password, b"saltysalt", 1003, dklen=16)


def _decrypt_chrome_value(encrypted_hex: str, key: bytes) -> str:
    """AES-128-CBC decrypt with IV of spaces, PKCS7 unpad.

    Same as Go's decryptChromeValue.
    """
    try:
        from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
    except ImportError:
        return ""

    try:
        raw = bytes.fromhex(encrypted_hex)
    except ValueError:
        return ""

    if len(raw) <= 3:
        return ""

    if raw[:3] != b"v10":
        return raw.decode("utf-8", errors="replace")

    ct = raw[3:]
    if len(ct) == 0 or len(ct) % 16 != 0:
        return ""

    try:
        iv = b" " * 16
        cipher = Cipher(algorithms.AES(key), modes.CBC(iv))
        decryptor = cipher.decryptor()
        pt = decryptor.update(ct) + decryptor.finalize()
        if pt:
            pad = pt[-1]
            if 0 < pad <= 16 and pad <= len(pt):
                pt = pt[:-pad]
        return pt.decode("utf-8", errors="replace")
    except Exception:
        return ""


def _read_cookies_from_db(cookies_path: str) -> list[ChromeCookie]:
    """Read cookies from Chrome SQLite DB with macOS keychain decryption.

    Same as Go's readCookiesFromDB: gets the Chrome Safe Storage password
    from keychain, derives the AES key, reads + decrypts cookie values.
    """
    if not os.path.isfile(cookies_path):
        return []

    key: bytes | None = None
    if platform.system() == "Darwin":
        try:
            result = subprocess.run(
                ["security", "find-generic-password", "-s", "Chrome Safe Storage", "-w"],
                capture_output=True, text=True, timeout=10,
            )
            if result.returncode == 0:
                password = result.stdout.strip().encode("utf-8")
                key = _derive_chrome_key(password)
        except Exception:
            pass

    try:
        conn = sqlite3.connect(f"file:{cookies_path}?mode=ro&immutable=1", uri=True)
        if key:
            cursor = conn.execute(
                "SELECT host_key, name, hex(encrypted_value), path, is_httponly, is_secure, "
                "CAST(expires_utc/1000000-11644473600 AS TEXT), "
                "CASE WHEN expires_utc=0 THEN 1 ELSE 0 END "
                "FROM cookies"
            )
        else:
            cursor = conn.execute(
                "SELECT host_key, name, '', path, is_httponly, is_secure, "
                "CAST(expires_utc/1000000-11644473600 AS TEXT), "
                "CASE WHEN expires_utc=0 THEN 1 ELSE 0 END "
                "FROM cookies"
            )

        cookies: list[ChromeCookie] = []
        for row in cursor:
            value = ""
            if key and row[2]:
                value = _decrypt_chrome_value(row[2], key)
            try:
                expires = float(row[6])
            except (ValueError, TypeError):
                expires = 0.0

            cookies.append(ChromeCookie(
                domain=row[0],
                name=row[1],
                value=value,
                path=row[3],
                http_only=bool(row[4]),
                secure=bool(row[5]),
                expires=expires,
                session=bool(row[7]),
                size=len(row[1]) + len(value),
            ))
        conn.close()
        cookies.sort(key=lambda c: (c.domain, c.name))
        return cookies
    except Exception:
        return []


def _first_stderr_line(s: str) -> str:
    for line in s.split("\n"):
        line = line.strip()
        if not line:
            continue
        return line[:300]
    return ""


# ---------------------------------------------------------------------------
# Main scan entry point (same flow as Go's ChromeScan)
# ---------------------------------------------------------------------------

def chrome_scan(output_dir: str = "") -> tuple[ChromeStatus, ModuleStatus]:
    mod_status = ModuleStatus(module=Module.CHROME)
    status = ChromeStatus()

    binary = _find_chrome_binary()
    if not binary:
        mod_status.note = "Google Chrome not found"
        return status, mod_status

    status.installed = True
    status.binary_path = binary

    try:
        result = subprocess.run(
            [binary, "--version"],
            capture_output=True, text=True, timeout=5,
        )
        status.version = result.stdout.strip()
    except Exception:
        pass

    user_data_dir = _chrome_user_data_dir()
    status.user_data_dir = user_data_dir
    if not user_data_dir:
        mod_status.note = "could not determine the default Chrome user-data directory on this platform"
        return status, mod_status
    if not os.path.isdir(user_data_dir):
        mod_status.note = "the default Chrome user-data directory does not exist (Chrome may never have run for this user)"
        return status, mod_status

    profiles_info = _discover_profiles(user_data_dir)
    if not profiles_info:
        profiles_info = [{"dir_name": "Default", "display_name": "Default", "gaia_name": ""}]
    mod_status.attempted = len(profiles_info)

    try:
        copy_dir, copied = _copy_profile_for_launch(user_data_dir, profiles_info)
    except Exception as e:
        msg = str(e)
        if "Operation not permitted" in msg:
            msg = (
                "macOS denied access to the Chrome data directory. "
                "Grant Full Disk Access to your terminal: "
                "System Settings > Privacy & Security > Full Disk Access > add your terminal app"
            )
        status.error = _first_stderr_line(msg)
        mod_status.note = f"failed to copy the user-data directory: {msg}"
        return status, mod_status
    status.copy_bytes = copied

    url = DEFAULT_CHROME_URL
    screenshot_dir = output_dir or tempfile.mkdtemp(prefix="secretscan-screenshots-")

    try:
        for pi in profiles_info:
            p = ChromeProfile(
                dir_name=pi["dir_name"],
                display_name=pi["display_name"],
                gaia_name=pi.get("gaia_name", ""),
                url=url,
            )

            png, cookies, err = _drive_chrome(binary, copy_dir, pi["dir_name"], url)
            if err:
                p.error = _first_stderr_line(err)
            else:
                p.launched = True
                p.cookies = cookies
                p.screenshot_png = png
                p.screenshot_bytes = len(png)
                mod_status.accessed += 1

                if screenshot_dir and png:
                    screenshot_path = os.path.join(screenshot_dir, f"chrome-{pi['dir_name']}.png")
                    try:
                        with open(screenshot_path, "wb") as f:
                            f.write(png)
                    except OSError:
                        pass

            status.profiles.append(p)
    finally:
        shutil.rmtree(copy_dir, ignore_errors=True)

    if platform.system() == "Darwin":
        for p in status.profiles:
            if len(p.cookies) == 0 and p.launched:
                cookies_path = os.path.join(user_data_dir, p.dir_name, "Cookies")
                db_cookies = _read_cookies_from_db(cookies_path)
                if db_cookies:
                    p.cookies = db_cookies

    total_cookies = sum(len(p.cookies) for p in status.profiles)
    mod_status.note = (
        f"copied the user-data directory and drove {len(status.profiles)} profile(s) headless; "
        f"read {total_cookies} cookie(s) total; the copy has been removed"
    )
    return status, mod_status
